    h, w = len(grid), len(grid[0])
    row_bands = [(start, start + 4) for start in range(0, h, 5)]
    col_bands = [(start, start + 2) for start in range(0, w, 3)]
    divider = grid[4][0]
    colors = {}
    for row in grid:
        for value in row:
            if value != divider:
                colors[value] = colors.get(value, 0) + 1
    background = max(colors, key=colors.get)
    out = [[background for _ in col_bands] for _ in row_bands]
    for ri, (r0, r1) in enumerate(row_bands):
        for ci, (c0, c1) in enumerate(col_bands):
            marks = sum(grid[r][c] != background and grid[r][c] != divider
                        for r in range(r0, min(r1, h))
                        for c in range(c0, min(c1, w)))
            if marks > 1:
                out[ri][ci] = 1
    return out
'''
